mod solution;

fn main() {
    let cases = [
    (r#"[1,2,3,4,5,null,6]"#, r#"4,5,2,6,3,1"#),
    (r#"[1,2,3]"#, r#"2,3,1"#),
    (r#"
[1,2,3]
"#, r#"2,3,1"#),
    (r#"  
[1,2,3,4,5,null,6]
  "#, r#"4,5,2,6,3,1"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS tree-postorder");
}
